const copy={
en:{captureTag:'ACTUAL ENGINE CAPTURE',nav:['The contract','Native captures','Inside Ignis','The horizon','The evidence'],eyebrow:'04 / THE ENGINE BEHIND THE SPARK',title:'Every detail.<br><em>MCP first.</em>',intro:'AI can control the entire engine. By design.',manifesto:'Create a scene. Configure a sense. Cast an ability. Inspect a decision. Reproduce a failure. Every controllable detail belongs in MCP before, or alongside, its visual control. This is the architecture of Ignis — and the rule for every system still to come.',human:'Human intent',agent:'AI agent',shared:'ONE SHARED CONTRACT',runtime:'RUST / 3D RUNTIME',stages:['Create','Run','Observe','Refine','Verify'],stageNotes:['Generate a seeded room from a recipe.','Advance a paused simulation by exactly 120 ticks.','Inspect NPC state and the reasons behind decisions.','Reverse the last authored edit as one transaction.','Run a saved scenario with typed checks and a finite budget.'],example:'CONTRACT EXAMPLE · NOT EXECUTED ON THIS PAGE',principles:['Same project. Same API.','No AI vendor lock-in.','Your game runs without its agent.'],atlasSmall:'06 / EXPLORE THE SYSTEMS',atlasTitle:'Under the<br><em>surface.</em>',atlasIntro:'A growing engine, already full of systems that interact. Open a layer. Follow the contract. See where the current implementation ends.',filters:['All systems','World','Minds & movement','Actions & effects','Evidence'],search:'Find a capability',results:'systems',limit:'CURRENT BOUNDARY',commands:'MCP OPERATIONS',inventory:`Explore ${operations.length} top-level commands`,empty:'No matching systems. Try another term.',roadSmall:'07 / THE COMPLETE ROADMAP',roadTitle:'A spark is<br>only <em>the start.</em>',roadIntro:'Sixteen connected domains. One rule: everything remains observable, procedural where relevant, and controllable through MCP. Explore the whole ambition.',roadNote:'Domains, not a release sequence. No completion percentages or promised dates. NPC v1 has technical closure; continuous worlds, presentation and production workflows keep evolving.',now:'IMPLEMENTED FOUNDATION',next:'THE REMAINING HORIZON',planned:'Planned system. Implementation is still ahead.',partial:'FOUNDATIONS IN PLACE',future:'PLANNED',focus:'EARLY SNAPSHOT FOCUS',proofSmall:'08 / REAL ENGINE. REAL BOUNDARIES.',proofTitle:'Built to be<br><em>understood.</em>',proofBody:'The editor, constructive sources and runtime belong to the same Rust engine. The images in this chapter are native captures. The opening web sculpture remains a separate brand experience.',facts:['Rust core. Native 3D.','Commercial source license. 1% of eligible Game profit after US$1M revenue.','MCP before or with every visual control.','Offline play. Optional networking.'],proofNote:'Active development. Implemented features are not the completed roadmap. macOS is the first validated platform. Web export and production distribution remain separate deliveries. This distribution uses the Ignis commercial source license; see LICENSE for the per-Game profit royalty.',source:'Content review: 03 NOV 2026 · source-backed native capabilities; experimental systems identified.',graphLabel:'Human and AI share the same command dispatcher and Rust engine.',roadLabel:'Choose a roadmap domain',loop:'DESCRIBE → BUILD → PLAY → OBSERVE → REFINE'},
pt:{captureTag:'CAPTURA REAL DA ENGINE',nav:['O contrato','Capturas nativas','Dentro da Ignis','O horizonte','A evidência'],eyebrow:'04 / A ENGINE POR TRÁS DA CENTELHA',title:'Cada detalhe.<br><em>MCP first.</em>',intro:'A IA pode controlar a engine inteira. Por arquitetura.',manifesto:'Crie uma cena. Configure um sentido. Lance uma habilidade. Inspecione uma decisão. Reproduza uma falha. Cada detalhe controlável precisa existir no MCP antes, ou junto, do controle visual. Essa é a arquitetura da Ignis — e a regra para todos os sistemas que ainda virão.',human:'Intenção humana',agent:'Agente de IA',shared:'UM CONTRATO COMPARTILHADO',runtime:'RUST / RUNTIME 3D',stages:['Criar','Executar','Observar','Refinar','Verificar'],stageNotes:['Gere uma sala a partir de receita e semente.','Avance uma simulação pausada em exatamente 120 ticks.','Inspecione o estado dos NPCs e os motivos das decisões.','Reverta a última edição autoral como uma transação.','Execute um cenário salvo, com checks tipados e orçamento finito.'],example:'EXEMPLO DO CONTRATO · NÃO EXECUTADO NESTA PÁGINA',principles:['Mesmo projeto. Mesma API.','Sem dependência de fornecedor de IA.','Seu jogo executa sem o agente.'],atlasSmall:'06 / EXPLORE OS SISTEMAS',atlasTitle:'Por baixo da<br><em>superfície.</em>',atlasIntro:'Uma engine em evolução, já cheia de sistemas que interagem. Abra uma camada. Siga o contrato. Veja até onde a implementação atual vai.',filters:['Todos os sistemas','Mundo','Mentes e movimento','Ações e efeitos','Evidência'],search:'Encontre uma capacidade',results:'sistemas',limit:'LIMITE ATUAL',commands:'OPERAÇÕES MCP',inventory:`Explore ${operations.length} comandos de primeiro nível`,empty:'Nenhum sistema encontrado. Tente outro termo.',roadSmall:'07 / O ROADMAP COMPLETO',roadTitle:'A centelha é<br>só <em>o começo.</em>',roadIntro:'Dezesseis domínios conectados. Uma regra: tudo observável, procedural onde fizer sentido e controlável pelo MCP. Explore a ambição inteira.',roadNote:'Domínios, não uma sequência de releases. Sem percentuais de conclusão ou datas prometidas. NPC v1 tem fechamento técnico; mundo contínuo, apresentação e fluxos de produção seguem evoluindo.',now:'FUNDAMENTO IMPLEMENTADO',next:'O HORIZONTE QUE FALTA',planned:'Sistema planejado. A implementação ainda está adiante.',partial:'FUNDAMENTOS PRESENTES',future:'PLANEJADO',focus:'FOCO DO RETRATO INICIAL',proofSmall:'08 / ENGINE REAL. LIMITES REAIS.',proofTitle:'Feita para ser<br><em>compreendida.</em>',proofBody:'Editor, fontes construtivas e runtime pertencem à mesma engine Rust. As imagens deste capítulo são capturas nativas. A escultura web da abertura continua sendo uma experiência de marca separada.',facts:['Núcleo Rust. 3D nativo.','Licença comercial de código disponível. 1% do lucro elegível após US$1M por jogo.','MCP antes ou junto de cada controle visual.','Jogo offline. Rede opcional.'],proofNote:'Desenvolvimento ativo. Features implementadas não são o roadmap concluído. macOS é a primeira plataforma validada. Exportação web e distribuição de produção seguem como entregas próprias. Esta distribuição usa a licença comercial Ignis; veja em LICENSE a participação no lucro por jogo.',source:'Revisão do conteúdo: 03 NOV 2026 · capacidades nativas conferidas; sistemas experimentais identificados.',graphLabel:'Humano e IA compartilham o mesmo dispatcher de comandos e engine Rust.',roadLabel:'Escolha um domínio do roadmap',loop:'DESCREVER → CONSTRUIR → JOGAR → OBSERVAR → REFINAR'}
};
const examples=[{op:'generate',recipe:{width:16,depth:14,seed:42,obstacles:4}},{op:'step',ticks:120},{op:'inspect_npcs'},{op:'undo'},{op:'run_scenario',path:'examples/quiet.scenario.json'}];
const rootSystems=[
 {id:'render',name:['Rendering','Renderização'],symbol:'◈'},
 {id:'botany',name:['Botany','Botânica'],symbol:'↟'},
 {id:'world',name:['World','Mundo'],symbol:'◇'},
 {id:'character',name:['Characters','Personagens'],symbol:'◎'},
 {id:'modeling',name:['Modeling','Modelagem'],symbol:'⌘'},
 {id:'npcs',name:['NPCs','NPCs'],symbol:'↗'},
 {id:'combat',name:['Combat','Combate'],symbol:'⌖'},
 {id:'network',name:['Multiplayer','Multiplayer'],symbol:'⋈'},
 {id:'tools',name:['Tools','Ferramentas'],symbol:'⌗'},
 {id:'all',name:['Everything','Tudo'],symbol:'✳'}
].map(g=>({...g,members:systems.flatMap((s,i)=>g.id==='all'||s.roots.includes(g.id)?[i]:[])}));
const galleryGroups={horizon:'render',sunset:'render',cottage:'modeling',landscape:'world',forest:'render',botany:'botany',roots:'botany',character:'character',editor:'tools',modeling:'modeling',groundcover:'botany',npc:'npcs',network:'network',planet:'world',young:'botany',mature:'botany',grass:'botany',sculpt:'modeling',face:'character'};
const galleryItems=['horizon','sunset','botany','cottage','groundcover'];
const extraCopy = {"gallerySmall": ["05 / BUILT HERE. RENDERED HERE.", "05 / CONSTRUÍDO AQUI. RENDERIZADO AQUI."], "galleryTitle": ["The spark<br><em>becomes a world.</em>", "A centelha<br><em>vira mundo.</em>"], "galleryIntro": ["Generate vegetation. Shape landscapes. Give characters purpose. Build with AI, inside an engine you control. This is what Ignis makes possible.", "Gere vegetação. Modele paisagens. Dê propósito aos personagens. Construa com IA, dentro de uma engine sob seu controle. É isso que a Ignis coloca nas suas mãos."], "renderSmall": ["ENGINEERING / REPRESENTATION + VISIBILITY", "ENGENHARIA / REPRESENTAÇÃO + VISIBILIDADE"], "renderTitle": ["Draw what contributes. Preserve what matters.", "Desenhar o que contribui. Preservar o que importa."], "renderBody": ["Our geometry and rendering stack combines content-based sharing, resident resources, consumed-attribute streams, conservative visibility, GPU occlusion and compiled distant representations. Editable sources and physical geometry remain separate from visual shortcuts. Region-compiled geometric LOD is an identified experimental path, disabled by default. Open Rendering below to explore every layer, including measured results and fallback boundaries.", "Nossa pilha de geometria e renderização combina compartilhamento por conteúdo, recursos residentes, atributos realmente consumidos, visibilidade conservadora, oclusão GPU e representações distantes compiladas. Fontes editáveis e geometria física ficam separadas dos atalhos visuais. LOD geométrico compilado por regiões é uma frente experimental identificada, desligada por padrão. Abra Renderização abaixo para explorar cada camada, medições e limites de fallback."], "loadMetric": ["players in specified local/loopback load scenarios", "jogadores nos cenários locais/loopback especificados"], "forestMetric": ["trees in the native dense-forest scene", "árvores na cena nativa de floresta densa"], "planetMetric": ["Earth-scale diameter in the opt-in planetary runtime", "de diâmetro terrestre no runtime planetário opt-in"], "metricLimit": ["Different scenarios and budgets. These figures are not a combined scene, universal FPS promise or production/WAN certification. Rendering comparisons are controlled A/B experiments within Ignis.", "Cenários e budgets distintos. Estes números não são uma cena combinada, promessa universal de FPS ou certificação de produção/WAN. Comparações de renderização são ensaios A/B controlados dentro da Ignis."]};
const rootContext = {"render": ["Ignis Horizon: native geometry, visibility and distant representations.", "Ignis Horizon: geometria nativa, visibilidade e representações distantes."], "botany": ["Constructive organs, branching architecture, chronological profiles, roots and native plant sources.", "Órgãos construtivos, arquitetura de ramificação, perfis de idade, raízes e fontes botânicas nativas."], "world": ["Editable topography, global coordinates, residency and physical exploration at planetary scale.", "Topografia editável, coordenadas globais, residência e exploração física em escala planetária."], "character": ["Body and face authoring, rigs, presentation and physical per-character control.", "Autoria de corpo e rosto, rigs, apresentação e controle físico por personagem."], "modeling": ["Build, select, sculpt and regenerate geometry through the editor and the same typed API.", "Construir, selecionar, esculpir e regenerar geometria pelo editor e pela mesma API tipada."], "npcs": ["NPC v1: knowledge, cognition, personality, mobility, tactics, routines and presentation.", "NPC v1: conhecimento, cognição, personalidade, mobilidade, tática, rotinas e apresentação."], "combat": ["One shared executor, from atomic costs to composed damage, areas, support and lifecycle.", "Um executor compartilhado, dos custos atômicos ao dano composto, áreas, apoio e ciclo de vida."], "network": ["Optional authoritative networking; offline single player remains a permanent requirement.", "Rede autoritativa opcional; single player offline continua requisito permanente."], "tools": ["Projects, shared control, diagnostics, reversible authoring and durable state.", "Projetos, controle compartilhado, diagnóstico, autoria reversível e estado durável."], "all": ["The complete reviewed inventory. Some capabilities appear in multiple root systems because their contracts are shared.", "O inventário completo revisado. Algumas capacidades pertencem a mais de um sistema raiz porque compartilham contratos."]};
const galleryNames = {"horizon":["Forested valleys","Vales e florestas"],"sunset":["Atmospheric layers","Camadas atmosféricas"],"cottage":["Architecture","Arquitetura"],"landscape": ["Terrain", "Terreno"], "forest": ["Forest", "Floresta"], "botany": ["Botany", "Botânica"], "roots": ["Roots", "Raízes"], "character": ["Characters", "Personagens"], "editor": ["Editor", "Editor"], "modeling": ["Modeling", "Modelagem"], "groundcover": ["Groundcover", "Cobertura"], "npc": ["NPCs", "NPCs"], "network": ["Multiplayer", "Multiplayer"], "planet": ["Planet", "Planeta"], "young": ["Age / young", "Idade / jovem"], "mature": ["Age / adult", "Idade / adulta"], "grass": ["Flowers", "Flores"], "sculpt": ["Sculpt", "Escultura"], "face": ["Face", "Rosto"]};
export function mountEngineChapters(onLayout){
 const root=document.getElementById('engine-chapters');let lang='en',idx=0,stage=0,selected=8,filter='render',query='',galleryIndex=0;
 const t=x=>x[idx];const esc=x=>x.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 root.innerHTML=`<nav class="engine-nav" aria-label="Engine"><a href="#protocol"></a><a href="#showcase"></a><a href="#capabilities"></a><a href="#roadmap"></a><a href="#engine-proof"></a></nav><section id="protocol" class="protocol engine-pad"><div class="engine-kicker" data-e="eyebrow"></div><h2 class="engine-mega" data-eh="title"></h2><div class="protocol-intro"><h3 data-e="intro"></h3><p data-e="manifesto"></p></div><div class="command-theatre"><div class="contract-graph" role="img"><svg viewBox="0 0 600 360" aria-hidden="true"><defs><radialGradient id="coreGlow"><stop stop-color="#ff603a" stop-opacity=".28"/><stop offset="1" stop-color="#ff603a" stop-opacity="0"/></radialGradient></defs><circle cx="300" cy="180" r="175" fill="url(#coreGlow)"/><g class="graph-orbits"><ellipse cx="300" cy="180" rx="175" ry="115"/><ellipse cx="300" cy="180" rx="115" ry="175"/><circle cx="300" cy="180" r="83"/></g><path class="graph-track" d="M20 60H140L250 150M580 60H460L350 150M300 210V330"/><path class="graph-flow" d="M20 60H140L250 150M580 60H460L350 150M300 210V330"/><circle class="graph-core" cx="300" cy="180" r="42"/><text x="300" y="189" text-anchor="middle">✳</text></svg><span class="graph-human" data-e="human"></span><span class="graph-agent" data-e="agent"></span><span class="graph-contract" data-e="shared"></span><span class="graph-runtime" data-e="runtime"></span></div><div class="command-console"><div class="stage-controls" role="group"></div><p class="stage-note"></p><pre tabindex="0"><code></code></pre><p class="example-note" data-e="example"></p></div></div><div class="protocol-principles"></div><div class="engine-loop" data-e="loop"></div></section><section id="showcase" class="native-showcase engine-pad"><div class="engine-kicker" data-new="gallerySmall"></div><div class="engine-heading"><h2 data-new-html="galleryTitle"></h2><p data-new="galleryIntro"></p></div><div class="product-stories"></div><div class="curated-heading"><span class="engine-kicker"></span><h3></h3><p></p></div><div class="native-gallery"><figure class="gallery-stage"></figure><div class="gallery-strip" role="group"></div></div></section><section id="capabilities" class="capabilities engine-pad"><div class="engine-kicker" data-e="atlasSmall"></div><div class="engine-heading"><h2 data-eh="atlasTitle"></h2><p data-e="atlasIntro"></p></div><div class="root-tabs-scroll"><div class="atlas-filters root-tabs" role="tablist"></div></div><div class="atlas-tools"><label class="atlas-search"><span data-e="search"></span><input type="search" maxlength="120"></label></div><div class="atlas-count" role="status" aria-live="polite"></div><p class="root-context"></p><div class="system-list" id="root-system-panel" role="tabpanel" tabindex="0"></div><p class="atlas-empty" hidden data-e="empty"></p><details class="command-inventory"><summary data-e="inventory"></summary><div>${operations.map(op=>`<code>${op}</code>`).join('')}</div></details></section><section id="roadmap" class="roadmap engine-pad"><div class="engine-kicker" data-e="roadSmall"></div><div class="engine-heading"><h2 data-eh="roadTitle"></h2><p data-e="roadIntro"></p></div><div class="roadmap-workspace"><div class="roadmap-map"><svg viewBox="0 0 400 400" preserveAspectRatio="none" aria-hidden="true"><path d="M50 50H350V150H50V250H350V350H50M50 50V350M150 50V350M250 50V350M350 50V350"/></svg><div class="roadmap-nodes" role="group"></div></div><article class="roadmap-detail" aria-live="polite"></article></div><p class="roadmap-note" data-e="roadNote"></p></section><section id="engine-proof" class="engine-proof engine-pad"><div class="engine-kicker" data-e="proofSmall"></div><div class="engine-heading"><h2 data-eh="proofTitle"></h2><p data-e="proofBody"></p></div><div class="proof-evidence"><figure><div class="capture-toolbar micro"><span>IGNIS / MCP</span><span data-e="captureTag">ACTUAL ENGINE CAPTURE</span></div><img src="assets/engine/editor.webp" data-alt="captureAlt" alt="Ignis native editor" width="1280" height="900" loading="lazy"><figcaption>NATIVE EDITOR / macOS / Metal</figcaption></figure><div class="proof-facts"></div></div><p class="engine-boundary" data-e="proofNote"></p><p class="content-snapshot" data-e="source"></p></section>`;
 const $=s=>root.querySelector(s);
 root.insertAdjacentHTML('beforeend','<dialog class="capture-dialog"><button class="capture-close" type="button"></button><figure></figure></dialog>');
 function mediaFigure(id,stage=false){const m=nativeMedia[id];return `<figure class="native-capture ${stage?'is-stage':''}"><button class="capture-open" data-capture="${id}" aria-label="${esc((idx?'Ampliar captura: ':'Enlarge capture: ')+t(m.caption))}"><img src="${m.src}" width="${m.width}" height="${m.height}" alt="${esc(t(m.caption))}" loading="lazy" decoding="async"><span aria-hidden="true">↗</span></button><figcaption>${esc(t(m.caption))}</figcaption></figure>`;}
 function renderGallery(){const id=galleryItems[galleryIndex];$('.gallery-stage').innerHTML=mediaFigure(id,true)+`<a class="gallery-explore" href="#capabilities" data-explore="${galleryGroups[id]}">${idx?'Explorar este sistema':'Explore this system'} <span aria-hidden="true">↗</span></a>`;$('.gallery-strip').setAttribute('aria-label',idx?'Escolher captura nativa':'Choose a native capture');$('.gallery-strip').innerHTML=galleryItems.map((id,i)=>`<button data-gallery="${i}" aria-pressed="${i===galleryIndex}"><img src="${nativeMedia[id].src}" width="140" height="86" alt="" loading="lazy"><span>${String(i+1).padStart(2,'0')} / ${galleryNames[id][idx]}</span></button>`).join('');onLayout();}
 function translateNew(){root.querySelectorAll('[data-new]').forEach(n=>n.textContent=extraCopy[n.dataset.new][idx]);root.querySelectorAll('[data-new-html]').forEach(n=>n.innerHTML=extraCopy[n.dataset.newHtml][idx]);$('.product-stories').innerHTML=renderStories(lang);const g=galleryCopy(lang);$('.curated-heading .engine-kicker').textContent=g.galleryTag;$('.curated-heading h3').innerHTML=g.galleryTitle;$('.curated-heading p').textContent=g.galleryBody;$('.capture-close').textContent=idx?'Fechar captura ×':'Close capture ×';$('.capture-dialog').setAttribute('aria-label',idx?'Captura nativa ampliada':'Enlarged native capture');}

 function renderStage(){const d=copy[lang];$('.stage-controls').innerHTML=d.stages.map((x,i)=>`<button aria-pressed="${stage===i}" data-stage="${i}"><span>0${i+1}</span>${x}</button>`).join('');$('.stage-note').textContent=d.stageNotes[stage];$('pre code').textContent=JSON.stringify({tool:'engine_command',arguments:{command:examples[stage]}},null,2);}
 function renderRoad(){const d=copy[lang],r=roadmap[selected];$('.roadmap-nodes').innerHTML=roadmap.map((r,i)=>`<button data-road="${i}" aria-pressed="${i===selected}" class=""><span>${r.id}</span><strong>${esc(t(r.title))}</strong><i class="${r.now[0]?'partial':'planned'}"></i></button>`).join('');$('.roadmap-nodes').setAttribute('aria-label',d.roadLabel);$('.roadmap-detail').innerHTML=`<div class="road-detail-top"><span>${r.id} / 16</span><span>${r.now[0]?d.partial:d.future}</span></div><h3>${esc(t(r.title))}</h3><div class="road-detail-now"><span>${d.now}</span><p>${esc(t(r.now)||d.planned)}</p></div><div class="road-detail-next"><span>${d.next}</span><p>${esc(t(r.next))}</p></div>`;onLayout();}
 function applyFilter(){const q=query.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();let count=0;root.querySelectorAll('.system-row').forEach((row,i)=>{const s=systems[i];const visible=rootSystems.find(g=>g.id===filter).members.includes(i)&&(!q||row.dataset.search.includes(q));row.hidden=!visible;if(visible){row.style.setProperty('--row-order',String(count));count++;}});$('.atlas-count').textContent=`${String(count).padStart(2,'0')} / ${systems.length} ${copy[lang].results}`;$('.atlas-empty').hidden=count!==0;root.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===filter;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});$('.system-list').setAttribute('aria-labelledby',`root-tab-${filter}`);$('.root-context').textContent=rootContext[filter][idx];onLayout();}
 function renderSystems(open){depthObserver.disconnect();releaseSurface();const d=copy[lang];$('.system-list').innerHTML=systems.map((s,i)=>`<details class="system-row" id="${s.id}" ${open.has(i)?'open':''} data-search="${esc((t(s.title)+' '+t(s.body)+' '+t(s.limit)+' '+(s.features?.[idx]||[]).join(' ')+' '+s.commands.join(' ')).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase())}"><summary><span class="system-glyph" aria-hidden="true"><svg viewBox="0 0 120 120"><g transform="rotate(${i*17} 60 60)"><ellipse cx="60" cy="60" rx="48" ry="19"/><ellipse cx="60" cy="60" rx="19" ry="48"/><path d="M60 7 106 33 106 87 60 113 14 87 14 33ZM60 7V113M14 33 106 87M106 33 14 87M14 33 60 60 106 33M14 87 60 60 106 87"/><circle cx="60" cy="60" r="31"/></g></svg></span><span class="system-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(t(s.title))}${s.status==='experimental'?`<small class="system-status">${idx?'EXPERIMENTAL':'EXPERIMENTAL'}</small>`:''}</h3><span class="system-toggle" aria-hidden="true">↗</span></summary><div class="system-content"><div class="system-description"><p>${esc(t(s.body))}</p>${s.features?`<ul>${s.features[idx].map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`:''}</div><div class="system-boundary"><span>${d.limit}</span><p>${esc(t(s.limit))}</p></div><div class="operation-chips"><span>${d.commands}</span>${s.commands.map(x=>`<code>${x}</code>`).join('')}</div>${s.media?mediaFigure(s.media):''}</div></details>`).join('');applyFilter();}
 function translate(next){const open=new Set([...root.querySelectorAll('.system-row')].flatMap((r,i)=>r.open?[i]:[]));lang=next==='pt'?'pt':'en';idx=lang==='pt'?1:0;const d=copy[lang];$('.contract-graph').setAttribute('aria-label',d.graphLabel);$('.stage-controls').setAttribute('aria-label',lang==='pt'?'Ciclo de comandos':'Command cycle');root.querySelectorAll('[data-e]').forEach(n=>n.textContent=d[n.dataset.e]);root.querySelectorAll('[data-eh]').forEach(n=>n.innerHTML=d[n.dataset.eh]);root.querySelectorAll('.engine-nav a').forEach((a,i)=>a.textContent=d.nav[i]);$('.engine-nav').setAttribute('aria-label',lang==='pt'?'Explore a engine':'Explore the engine');$('.atlas-filters').setAttribute('aria-label',lang==='pt'?'Sistemas da engine':'Engine systems');$('.atlas-filters').innerHTML=rootSystems.map((g,i)=>`<button id="root-tab-${g.id}" role="tab" data-filter="${g.id}" aria-selected="${filter===g.id}" aria-controls="root-system-panel" tabindex="${filter===g.id?0:-1}"><span class="root-tab-face"><span class="root-tab-top"><span>${String(i+1).padStart(2,'0')}</span><span aria-hidden="true">${g.symbol}</span></span><strong>${esc(t(g.name))}</strong><span class="root-tab-bottom"><span>${String(g.members.length).padStart(2,'0')}</span><span aria-hidden="true">↗</span></span></span></button>`).join('');$('.protocol-principles').innerHTML=d.principles.map((x,i)=>`<p><span>0${i+1} /</span>${esc(x)}</p>`).join('');$('.proof-facts').innerHTML=d.facts.map((x,i)=>`<p><span>0${i+1}</span>${esc(x)}</p>`).join('');$('.proof-evidence figcaption').textContent=lang==='pt'?'EDITOR NATIVO / macOS / Metal':'NATIVE EDITOR / macOS / Metal';renderStage();renderSystems(open);root.querySelectorAll('.system-row').forEach(row=>depthObserver.observe(row));renderRoad();renderGallery();translateNew();}
 root.addEventListener('click',e=>{const link=e.target.closest('[data-explore]');if(link){filter=link.dataset.explore;query='';$('.atlas-search input').value='';applyFilter();}const b=e.target.closest('button');if(!b)return;if(b.dataset.gallery!==undefined){galleryIndex=Number(b.dataset.gallery);renderGallery();$(`[data-gallery="${galleryIndex}"]`).focus({preventScroll:true});return;}if(b.dataset.capture){const id=b.dataset.capture,m=nativeMedia[id];$('.capture-dialog figure').innerHTML=`<img src="${m.src}" width="${m.width}" height="${m.height}" alt="${esc(t(m.caption))}"><figcaption>${esc(t(m.caption))}</figcaption>`;$('.capture-dialog').showModal();return;}if(b.classList.contains('capture-close')){$('.capture-dialog').close();return;}if(b.dataset.stage!==undefined){stage=Number(b.dataset.stage);renderStage();$('.stage-controls').querySelector(`[data-stage="${stage}"]`).focus({preventScroll:true});onLayout();}if(b.dataset.filter){filter=b.dataset.filter;applyFilter();}if(b.dataset.road!==undefined){selected=Number(b.dataset.road);renderRoad();$('.roadmap-nodes').querySelector(`[data-road="${selected}"]`).focus({preventScroll:true});}});
 root.addEventListener('keydown',e=>{const tab=e.target.closest('[data-filter]');if(tab){const i=rootSystems.findIndex(g=>g.id===tab.dataset.filter),delta={ArrowRight:1,ArrowLeft:-1}[e.key];if(delta!==undefined||e.key==='Home'||e.key==='End'){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?rootSystems.length-1:(i+delta+rootSystems.length)%rootSystems.length;filter=rootSystems[next].id;applyFilter();const target=$(`[data-filter="${filter}"]`);target.focus({preventScroll:true});target.scrollIntoView({block:'nearest',inline:'nearest',behavior:'instant'});}return;}const b=e.target.closest('[data-road]');if(!b)return;const delta={ArrowRight:1,ArrowLeft:-1,ArrowDown:4,ArrowUp:-4}[e.key];if(delta!==undefined||e.key==='Home'||e.key==='End'){e.preventDefault();selected=e.key==='Home'?0:e.key==='End'?15:(Number(b.dataset.road)+delta+16)%16;renderRoad();$(`[data-road="${selected}"]`).focus({preventScroll:true});}});
 $('.atlas-search input').addEventListener('input',e=>{query=e.target.value;applyFilter();});root.addEventListener('toggle',()=>onLayout(),true);
 const motionPreference=matchMedia('(prefers-reduced-motion:reduce)'),finePointer=matchMedia('(hover:hover) and (pointer:fine)');
 let activeSurface=null,surfaceBounds=null;
 const motionAllowed=()=>!motionPreference.matches&&!document.hidden&&!document.body.classList.contains('motion-paused');
 function releaseSurface(){if(activeSurface){activeSurface.style.removeProperty('--tilt-x');activeSurface.style.removeProperty('--tilt-y');activeSurface.style.removeProperty('--spot-x');activeSurface.style.removeProperty('--spot-y');activeSurface.classList.remove('tracking');}activeSurface=null;surfaceBounds=null;}
 root.addEventListener('pointerover',e=>{const surface=e.target.closest('.system-row summary');if(surface===activeSurface)return;releaseSurface();if(surface&&finePointer.matches&&motionAllowed()){activeSurface=surface;surfaceBounds=surface.getBoundingClientRect();surface.classList.add('tracking');}});
 root.addEventListener('pointermove',e=>{if(!activeSurface||!surfaceBounds||!motionAllowed())return;const x=Math.max(0,Math.min(1,(e.clientX-surfaceBounds.left)/surfaceBounds.width)),y=Math.max(0,Math.min(1,(e.clientY-surfaceBounds.top)/surfaceBounds.height));activeSurface.style.setProperty('--tilt-x',`${(0.5-y)*8}deg`);activeSurface.style.setProperty('--tilt-y',`${(x-0.5)*5}deg`);activeSurface.style.setProperty('--spot-x',`${x*100}%`);activeSurface.style.setProperty('--spot-y',`${y*100}%`);});
 root.addEventListener('pointerout',e=>{if(activeSurface&&!activeSurface.contains(e.relatedTarget))releaseSurface();});
 addEventListener('scroll',releaseSurface,{passive:true});addEventListener('resize',releaseSurface,{passive:true});
 motionPreference.addEventListener('change',releaseSurface);
 const pauseObserver=new MutationObserver(releaseSurface);pauseObserver.observe(document.body,{attributes:true,attributeFilter:['class']});
 const depthObserver=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('depth-visible',e.isIntersecting)),{threshold:0.08});
 document.addEventListener('visibilitychange',releaseSurface);
 document.addEventListener('ignis:language',e=>translate(e.detail));
 const observer=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('is-near',e.isIntersecting)),{rootMargin:'80px'});observer.observe($('.contract-graph'));
 document.addEventListener('visibilitychange',()=>root.classList.toggle('engine-hidden',document.hidden));
 translate(document.documentElement.lang.startsWith('pt')?'pt':'en');
 addEventListener('load',()=>{const target=document.getElementById(location.hash.slice(1));if(target&&root.contains(target))target.scrollIntoView({behavior:'instant'});},{once:true});
}
